SELECT Name, Country, Age FROM singer ORDER BY Age DESC LIMIT 100;
SELECT AVG(Age), MIN(Age), MAX(Age) FROM singer WHERE Country = 'France'
SELECT AVG(Age), MIN(Age), MAX(Age) FROM singer;
SELECT singer.Name, singer.Age AS Age FROM singer INNER JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE singer.Age = (SELECT MIN(Age) FROM singer)
SELECT singer.Name, singer.Age AS Age, singer_in_concert.Song_release_year FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID WHERE singer_in_concert.concert.Year = (SELECT MAX(Song_release_year) FROM concert) GROUP BY singer.Name
SELECT DISTINCT Country FROM singer JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID WHERE Age > 20;
SELECT DISTINCT Country FROM singer WHERE Age > 20
SELECT singer.Country, COUNT(singer_in_concert.Singer_ID) AS singer_count FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID GROUP BY singer.Country
SELECT DISTINCT singer.Country, COUNT(singer.Country) AS count_per_nation FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY singer.Country;
SELECT singer.Name AS Song_Name, singer.Age AS Age FROM singer INNER JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE singer.Age > (SELECT AVG(singer.Age) FROM singer)
SELECT singer.Song_Name FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID WHERE singer.Age > (SELECT AVG(Age) FROM singer)
SELECT stadium.Location, stadium.Name FROM stadium JOIN singer_in_concert ON stadium.Stadium_ID = singer_in_concert.Stadium_ID WHERE singer_in_concert.Singer_ID IN (SELECT Singer_ID FROM singer_in_concert WHERE concert.Year = ?) AND concert.Year BETWEEN 5000 AND 10000;
SELECT s.Name, c.Stadium_ID FROM singer s INNER JOIN singer_in_concert c ON s.Singer_ID = c.Singer_ID INNER JOIN concert c ON c.concert_ID = c.concert_ID WHERE c.Average >= 5000 AND c.Average <= 10000;
