SELECT airlines.Airline, airports.CountryAbbrev FROM airlines JOIN airports ON airlines.Airline = airports.AirportCode WHERE airports.AirportCode = 'AHD'
SELECT Airline FROM flights JOIN airports ON flights.SourceAirport = airports.AirportCode JOIN airlines ON flights.Airline = airlines.Airline WHERE flights.SourceAirport = 'APG' AND flights.DestAirport = 'CVO';
SELECT DISTINCT Airline FROM flights JOIN airports ON flights.SourceAirport = airports.AirportCode JOIN airlines ON airports.Country = airlines.Country WHERE flights.Airline = 'APG' OR flights.Airline = 'CVO';
SELECT Airline, Abbreviation FROM airlines WHERE Abbreviation != 'APG' AND FlightNo IS NULL;
SELECT Airline FROM flights WHERE DestAirport NOT IN (SELECT AirportCode FROM airports WHERE AirportCode = 'CVO') GROUP BY Airline
SELECT flights.FlightNo FROM flights INNER JOIN airlines ON flights.Airline = airlines.Airline WHERE airlines.Abbreviation = 'United Airlines' LIMIT 100
SELECT flights.FlightNo FROM flights JOIN airlines ON flights.Airline = airlines.Airline;
SELECT flights.FlightNo FROM flights WHERE flights.Airline = (SELECT Airline FROM airlines WHERE Airline = 'APG')
SELECT flights.FlightNo FROM flights INNER JOIN airports ON flights.SourceAirport = airports.AirportCode WHERE flights.Airline = 'APG' AND flights.DestAirport = NULL;
SELECT flights.FlightNo FROM flights JOIN airports ON flights.SourceAirport = airports.AirportCode;
SELECT flights.FlightNo FROM flights JOIN airports ON flights.SourceAirport = airports.AirportCode;
SELECT flights.FlightNo FROM flights WHERE flights.Airline = (SELECT Airline FROM airlines WHERE airports.Country = 'Aberdeen')
SELECT flights.FlightNo FROM flights JOIN airports ON flights.SourceAirport = airports.AirportCode WHERE airports.City = 'Aberdeen' AND flights.Airline = 'airlines.uid' AND flights.DestAirport = airports.AirportCode
SELECT flights.FlightNo FROM flights JOIN airports ON flights.SourceAirport = airports.AirportCode;
SELECT flights.Airline, flights.FlightNo FROM flights JOIN airports ON flights.DestAirport = airports.AirportCode WHERE airports.City = 'Aberdeen'
SELECT COUNT(*) FROM airports WHERE AirportCode IN (SELECT AirportCode FROM flights WHERE DestAirport = 'Aberdeen' OR DestAirport = 'Abilene')
SELECT COUNT(DISTINCT flights.DestAirport) FROM airports INNER JOIN flights ON airports.AirportCode = flights.SourceAirport;
SELECT airports.AirportName FROM airports WHERE airports.CountryAbbrev NOT IN (SELECT CountryAbbrev FROM flights JOIN airports ON flights.SourceAirport = airports.AirportCode AND flights.DestAirport = airports.AirportCode)
SELECT airports.AirportCode FROM airports WHERE airports.AirportCode NOT IN (SELECT flights.DestAirport FROM flights)
SELECT Name FROM employee ORDER BY Age DESC;
SELECT Name, Age FROM employee ORDER BY Age ASC;
SELECT City, COUNT(DISTINCT Employee_ID) AS UniqueEmployees FROM employee JOIN hiring ON hiring.Employee_ID = employee.Employee_ID GROUP BY City HAVING COUNT(DISTINCT Employee_ID) > 1 AND Age < 30;
SELECT City FROM employee WHERE Age < 30 AND Employee_ID IN (SELECT Employee_ID FROM hiring WHERE Start_from <= 30 AND Is_full_time = 1)
SELECT COUNT(*) AS Number_of_shops_per_place FROM shop;
SELECT COUNT(DISTINCT employee.City), COUNT(DISTINCT shop.Location) FROM employee JOIN shop ON employee.City = shop.Location;
SELECT e.Manager_name, s.District FROM employee e JOIN shop s ON e.Employee_ID = s.Manager_name WHERE s.Number_products = (SELECT MAX(Number_products) FROM shop)
SELECT e.Name, s.District FROM employee e JOIN shop s ON e.Manager_name = s.Manager_name ORDER BY s.Number_products DESC;
SELECT e.Name, s.Location, s.District, e.Manager_name FROM employee e JOIN shop s ON e.Employee_ID = s.Manager_name ORDER BY s.Number_products DESC;
SELECT e.Name, s.Location, s.District, s.Number_products FROM employee e JOIN shop s ON e.Employee_ID = s.Manager_name ORDER BY s.Number_products DESC;
SELECT e.Name AS Store_Name FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID JOIN shop s ON h.Shop_ID = s.Shop_ID WHERE s.Number_products > (SELECT AVG(Number_products) FROM shop)
SELECT Name FROM shop WHERE Number_products > (SELECT AVG(Number_products) FROM shop)
SELECT e.Name FROM employee e JOIN evaluation e ON e.Employee_ID = evaluation.Employee_ID WHERE evaluation.Bonus IS MAX(evaluation.Bonus)
SELECT Name FROM employee ORDER BY Bonus DESC LIMIT 1
SELECT e.Name, h.Shop_ID FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID JOIN shop s ON h.Shop_ID = s.Shop_ID GROUP BY e.Name ORDER BY s.Number_products DESC LIMIT 1;
SELECT Name FROM shop WHERE Shop_ID IN (SELECT Shop_ID FROM hiring WHERE Is_full_time = TRUE)
SELECT Name FROM shop WHERE Manager_name IS NULL
SELECT Name FROM shop WHERE Manager_name IS NULL;
SELECT District FROM shop WHERE District IN (SELECT District FROM shop WHERE Number_products < 3000 AND Manager_name IS NULL) AND District IN (SELECT District FROM shop WHERE Number_products > 10000 AND Manager_name IS NOT NULL)
SELECT DISTINCT District FROM shop WHERE Number_products < 3000 AND Number_products > 10000
