SELECT DISTINCT teacher.Hometown, COUNT(teacher.Teacher_ID) AS Teacher_Count FROM teacher JOIN course_arrange ON course_arrange.Teacher_ID = teacher.Teacher_ID GROUP BY teacher.Hometown;
SELECT DISTINCT teacher.Hometown, COUNT(*) AS number_of_teachers_per_place FROM course_arrange JOIN teacher ON course_arrange.Teacher_ID = teacher.Teacher_ID GROUP BY teacher.Hometown;
SELECT DISTINCT teacher.Name, teacher.Hometown FROM teacher JOIN course_arrange ON teacher.Teacher_ID = course_arrange.Teacher_ID JOIN course ON course.Course_ID = course_arrange.Course_ID ORDER BY teacher.Hometown ASC;
SELECT DISTINCT teacher.Name AS Town FROM teacher JOIN course_arrange ON course_arrange.Course_ID = course.Course_ID JOIN course ON course.Course_ID = course_arrange.Course_ID WHERE course_arrange.Teacher_ID IN (SELECT Teacher_ID FROM teacher WHERE teacher.Age >= 30 AND teacher.Hometown = 'New York')
SELECT teacher.Name FROM teacher JOIN course_arrange ON teacher.Teacher_ID = course_arrange.Teacher_ID WHERE course_arrange.Course_ID = (SELECT Course_ID FROM course WHERE Course = 'Math') GROUP BY teacher.Teacher_ID
SELECT Name FROM teacher WHERE Teacher_ID IN (SELECT Teacher_ID FROM course_arrange JOIN course ON course_arrange.Course_ID = course.Course_ID WHERE course.Course = 'math')
SELECT teacher.Name FROM teacher INNER JOIN course_arrange ON course_arrange.Course_ID = course.Course_ID WHERE course_arrange.Teacher_ID IS NULL;
SELECT teacher.Name FROM teacher JOIN course_arrange ON course_arrange.Course_ID = course.Course_ID WHERE course_arrange.Teacher_ID IS NULL
SELECT COUNT(DISTINCT visitor.Level_of_membership) FROM visitor JOIN visit ON visit.visitor_ID = visitor.ID WHERE visit.Museum_ID = museum.Museum_ID AND visitor.Age < 30;
SELECT visitor.Name FROM visitor JOIN visit ON visit.visitor_ID = visitor.ID WHERE visit.Level_of_membership > 4 ORDER BY Level_of_membership DESC;
SELECT AVG(visitor.Age) FROM visitor INNER JOIN visit ON visit.visitor_ID = visitor.ID WHERE visit.Museum_ID = museum.Museum_ID AND visitor.Level_of_membership <= 4
SELECT museum.Museum_ID, museum.Name, COUNT(visitor.ID) AS total_visitors FROM museum INNER JOIN visit ON museum.Museum_ID = visit.Museum_ID INNER JOIN visitor ON visit.visitor_ID = visitor.ID GROUP BY museum.Museum_ID ORDER BY COUNT(visitor.ID) DESC;
SELECT AVG(museum.Num_of_Staff) FROM museum JOIN visit ON museum.Museum_ID = visit.Museum_ID WHERE visit.Open_Year < '2009'
SELECT museum.Open_Year, museum.Num_of_Staff FROM museum;
SELECT Name FROM museum WHERE Num_of_Staff > (SELECT MIN(Num_of_Staff) FROM visit WHERE Open_Year > '2010')
SELECT v.ID, v.Name, v.Age FROM visitor v JOIN visit v2 ON v.ID = v2.visitor_ID JOIN museum m ON v2.Museum_ID = m.Museum_ID WHERE v2.Num_of_Ticket > 0;
SELECT id, name, membership_level FROM visitor JOIN visit ON visit.visitor_ID = visitor.ID WHERE visit.Total_spent = (SELECT MAX(Num_of_Ticket) * Total_spent FROM visit GROUP BY visit.Museum_ID)
SELECT museum.Museum_ID, museum.Name, COUNT(visit.visitor_ID) AS total_visits FROM museum JOIN visit ON museum.Museum_ID = visit.Museum_ID GROUP BY museum.Museum_ID
SELECT museum.Name FROM museum JOIN visit ON museum.Museum_ID = visit.Museum_ID WHERE visit.visitor_ID IS NULL
SELECT visitor.Name, visitor.Age FROM visitor JOIN visit ON visit.visitor_ID = visitor.ID JOIN museum ON visit.Museum_ID = museum.Museum_ID GROUP BY visitor.Name, visitor.Age ORDER BY visitor.Age DESC;
SELECT SUM(visit.Total_spent) AS total_ticket_expense FROM visit INNER JOIN museum ON visit.Museum_ID = museum.Museum_ID;
SELECT players.first_name, players.birth_date FROM players JOIN matches ON players.player_id = matches.loser_id WHERE players.country_code = 'USA' ORDER BY players.first_name;
SELECT first_name, birth_date FROM players JOIN matches ON players.player_id = matches.loser_id WHERE country_code = 'USA' ORDER BY first_name
SELECT tourney_name FROM matches JOIN rankings ON matches.winner_id = rankings.player_id WHERE tourney_name IS NOT NULL AND (SELECT COUNT(*) FROM matches WHERE tourney_id = matches.tourney_id AND matches.best_of > 10)
SELECT tourney_name FROM matches JOIN rankings ON matches.loser_id = rankings.player_id WHERE matches.best_of > 10;
SELECT players.first_name, players.last_name FROM players JOIN matches ON players.player_id = matches.winner_id JOIN rankings ON players.player_id = rankings.player_id WHERE matches.year IN ('2013', '2016') GROUP BY players.first_name, players.last_name
SELECT p.first_name, p.last_name FROM players p JOIN matches m ON p.player_id = m.winner_id WHERE m.year IN (2013, 2016) AND p.first_name != '' AND p.last_name != ''
SELECT COUNT(*) FROM matches WHERE year IN (2013, 2016)
SELECT COUNT(*) FROM matches WHERE year IN (2013, 2016)
SELECT p.first_name, p.country_code FROM players p JOIN matches m ON p.player_id = m.winner_id JOIN rankings r ON m.match_num = r.ranking_date WHERE p.country_code = (SELECT country_code FROM players WHERE first_name = 'WTA Championships' AND winner_age = (SELECT winner_age FROM matches WHERE winner_id = (SELECT winner_id FROM matches WHERE winner_name = 'Australian Open')))
SELECT p.first_name, p.country_code FROM players p JOIN matches m ON p.player_id = m.winner_id JOIN rankings r ON p.player_id = r.player_id WHERE m.tourney_name = 'WTA Championships' AND m.tourney_name = 'Australian Open'
SELECT players.first_name, players.country_code FROM players JOIN matches ON players.player_id = matches.winner_id ORDER BY players.birth_date DESC LIMIT 1;
SELECT p.first_name, p.country_code FROM players p JOIN rankings r ON p.player_id = r.player_id WHERE r.ranking = (SELECT MAX(ranking) FROM rankings)
SELECT first_name, last_name FROM players ORDER BY age ASC;
SELECT p.first_name, p.last_name, p.birth_date, p.country_code, r.ranking, r.ranking_points FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY p.birth_date DESC;
SELECT p.first_name, p.last_name FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.loser_hand = 'left' ORDER BY p.winner_age;
SELECT p.first_name, p.last_name, m.loser_age, m.loser_entry, m.loser_hand, m.loser_ht, m.loser_id, m.loser_name, m.loser_rank, m.loser_rank_points, m.loser_seed, m.match_num, m.minutes, m.round, m.score, m.surface, m.tourney_date, m.tourney_id, m.tourney_level, m.tourney_name, m.winner_age, m.winner_entry, m.winner_hand, m.winner_ht, m.winner_id, m.winner_name, m.winner_rank, m.winner_rank_points, m.winner_seed, m.year FROM players p INNER JOIN matches m ON p.player_id = m.loser_id ORDER BY m.loser_age
SELECT players.first_name, matches.winner_rank_points AS winner_rank_points FROM players INNER JOIN matches ON matches.winner_id = players.player_id ORDER BY winner_rank_points DESC;
SELECT p.first_name, p.last_name, p.hand, p.birth_date, p.country_code, r.ranking_points FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.ranking_points DESC LIMIT 1;
SELECT p.first_name, p.last_name, p.country_code FROM players p JOIN matches m ON p.player_id = m.winner_id JOIN rankings r ON m.match_num = r.match_num WHERE r.ranking_points = (SELECT MAX(ranking_points) FROM rankings r) ORDER BY p.first_name, p.last_name LIMIT 1;
