SELECT p.first_name, p.last_name FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.minutes = (SELECT MAX(minutes) FROM matches m2 WHERE m2.round = m.round AND m2.year = m.year)
SELECT p.first_name, p.last_name AS winner, p.last_name AS loser FROM players p JOIN matches m ON p.player_id = m.loser_id WHERE m.best_of = (SELECT MAX(best_of) FROM matches m2 WHERE m2.round = m.round AND m2.best_of = m.best_of) GROUP BY p.first_name, p.last_name;
SELECT COUNT(*) AS number_of_players_per_nation FROM players JOIN rankings ON players.player_id = rankings.player_id;
SELECT country_code, COUNT(*) AS count FROM players GROUP BY country_code
SELECT country_code FROM players JOIN rankings ON players.player_id = rankings.player_id ORDER BY ranking_points DESC LIMIT 1;
SELECT country_code FROM players WHERE player_id IN (SELECT player_id FROM matches WHERE winner_id = (SELECT player_id FROM rankings WHERE ranking_points = (SELECT MAX(ranking_points) FROM rankings)) GROUP BY player_id) ORDER BY country_code DESC LIMIT 1;
SELECT player_id, country_code FROM players JOIN matches ON matches.winner_id = players.player_id WHERE matches.round = 1 AND matches.minutes > 5000
SELECT country_code FROM players JOIN matches ON players.player_id = matches.loser_id WHERE matches.round = 1 AND matches.minutes > 50;
SELECT p.first_name, p.rankings.ranking FROM players p JOIN rankings ON p.player_id = rankings.player_id ORDER BY rankings.ranking ASC LIMIT 3;
SELECT p.first_name, p.last_name, r.ranking FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.ranking ASC LIMIT 3;
SELECT COUNT(DISTINCT players.player_id) FROM players INNER JOIN matches ON matches.winner_id = players.player_id WHERE players.hand = 'left' AND matches.loser_hand = 'right'
SELECT COUNT(*) FROM players INNER JOIN matches ON players.player_id = matches.winner_id;
SELECT COUNT(*) FROM ship WHERE disposition_of_ship = 'Captured'
SELECT b.id, b.name, d.killed, d.injured FROM battle b JOIN death d ON b.id = d.caused_by_ship_id WHERE d.killed > 10
SELECT ship.id, ship.name, COUNT(death.injured) AS total_injuries FROM ship JOIN death ON ship.id = death.caused_by_ship_id GROUP BY ship.id, ship.name ORDER BY total_injuries DESC;
SELECT battle.name, battle.date FROM battle JOIN ship ON battle.id = ship.lost_in_battle WHERE ship.name = 'HMS Atalanta' AND battle.latin_commander = 'Lettice'
SELECT battle.name, battle.result, battle.bulgarian_commander FROM battle JOIN ship ON battle.id = ship.lost_in_battle WHERE ship.location = 'English Channel' AND ship.disposition_of_ship = 'lost' AND battle.result IS NULL;
SELECT course_description, course_name, degree_summary_description, degree_program_id, department_id, department_name, semester_name, semester_description FROM Courses JOIN Degree_Programs ON Courses.course_id = Degree_Programs.degree_program_id JOIN Departments ON Degree_Programs.department_id = Departments.department_id JOIN Semesters ON Degree_Programs.semester_id = Semesters.semester_id;
SELECT course_description FROM Courses;
SELECT Addresses.zip_postcode FROM Addresses;
SELECT zip_postcode FROM Addresses WHERE city = 'Port Chelsea';
SELECT s.last_name, s.student_id FROM Students s JOIN Addresses a ON s.current_address_id = a.address_id JOIN Addresses p ON s.permanent_address_id = p.address_id WHERE s.state_province_county = 'North Carolina' AND s.date_left IS NULL;
SELECT last_name FROM Students WHERE permanent_address_id IN (SELECT address_id FROM Addresses WHERE state_province_county = 'North Carolina') AND date_first_registered IS NULL;
SELECT s.last_name, s.cell_mobile_number FROM Students s JOIN Addresses a ON s.current_address_id = a.address_id WHERE s.last_name = 'Timmothy' LIMIT 1
SELECT student_id, cell_mobile_number FROM Students WHERE first_name = 'Timmothy' AND last_name = 'Ward';
SELECT s.first_name, s.middle_name, s.last_name, s.date_first_registered FROM Students s WHERE s.date_first_registered IS NULL OR s.date_first_registered = (SELECT MIN(date_first_registered) FROM Students) ORDER BY s.date_first_registered;
SELECT s.first_name, s.middle_name, s.last_name, s.date_first_registered, s.date_left FROM Students s JOIN Transcripts t ON s.student_id = t.transcript_id JOIN Transcript_Contents tc ON t.transcript_id = tc.transcript_id JOIN Student_Enrolment_Courses sec ON tc.student_course_id = sec.student_course_id JOIN Courses c ON sec.course_id = c.course_id JOIN Sections ssec ON sec.course_id = ssec.course_id JOIN Departments d ON ssec.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Semester ssem ON ssec.semester_id = ssem.semester_id JOIN Semesters ssem2 ON ssem2.semester_id = ssem.semester_id;
SELECT DISTINCT s.first_name, s.middle_name, s.last_name, s.date_first_registered, s.date_left FROM Students s WHERE s.date_first_registered = (SELECT MIN(date_first_registered) FROM Students) ORDER BY s.date_first_registered;
SELECT s.id, s.first_name, s.middle_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON s.section_id = ssec.section_id JOIN Departments d ON ssec.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Transcripts t ON ssec.transcript_id = t.transcript_id JOIN Transcript_Contents tc ON tc.student_course_id = ssec.student_course_id JOIN Courses c ON ssec.course_id = c.course_id JOIN Sections ssec ON s.section_id = ssec.section_id JOIN Departments d ON ssec.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Transcripts t ON ssec.transcript_id = t.transcript_id JOIN Transcript_Contents tc ON tc.student_course_id = ssec.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON s.section_id = ssec.section_id JOIN Departments d ON ssec.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Transcripts t ON ssec.transcript_id = t.transcript_id JOIN Transcript_Contents tc ON tc.student_course_id = ssec.student_course_id
SELECT s.id, s.line_1, s.line_2 FROM Addresses s JOIN Students s ON s.address_id = s.address_id;
SELECT DISTINCT Semester.semester_name AS semester, Semester.semester_description AS semester_description FROM Semesters INNER JOIN Students ON Students.student_id = Semesters.semester_id;
SELECT DISTINCT S.semester_id FROM Semesters S JOIN Students S2 ON S.semester_id = S2.date_left JOIN Students S3 ON S.semester_id = S3.date_left JOIN Student_Enrolment_Courses SC ON S3.student_id = SC.student_course_id JOIN Courses C ON SC.course_id = C.course_id JOIN Degree_Programs DP ON DP.degree_program_id = S3.department_id JOIN Departments D ON D.department_id = DP.department_id;
