SELECT s.first_name, s.middle_name, s.last_name FROM Students s WHERE s.cell_mobile_number = '09700166582' OR s.permanent_address_id = (SELECT address_id FROM Addresses WHERE city = 'Haiti') ORDER BY s.first_name;
